{
  "claims": [
    {
      "claim": "Adefovir dipivoxil, the bis(pivaloyloxymethyl) ester of the query phosphonate, achieved only ~30% oral bioavailability in fasting humans after masking the charged phosphonic acid; an in-situ rat ileum study showed the diester increased total adefovir transport ~10-fold over the parent compound, indicating that the free phosphonate query is intrinsically less permeable.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 11"],
      "record_ids": ["Record 11-1", "Record 11-2", "Record 11-6"]
    },
    {
      "claim": "Tenofovir, a closely related acyclic adenine phosphonate, has low oral bioavailability as the free phosphonate in preclinical studies and very low Caco-2 permeability (~0.1 x 10^-6 cm/s); its human F of about 25% is observed only after administration of the diester prodrug tenofovir DF, demonstrating that the free phosphonate form is intrinsically poorly absorbed.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 13"],
      "record_ids": ["Record 13-1", "Record 13-2", "Record 13-3", "Record 13-4", "Record 13-5", "Record 13-6", "Record 13-7", "Record 13-8", "Record 13-9", "Record 13-10", "Record 13-17", "Record 13-18", "Record 13-21"]
    },
    {
      "claim": "Oral administration of many diester prodrugs of an adenine-linked phosphonate in mice released the phosphonate with mostly low bioavailability (0-10%), with only rare values of 22-26%, reinforcing that the free ionized phosphonate is poorly absorbed and usually fails the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 12"],
      "record_ids": ["Record 12-1", "Record 12-5", "Record 12-12", "Record 12-13", "Record 12-14", "Record 12-15", "Record 12-16"]
    },
    {
      "claim": "ATP, a highly charged polyphosphate nucleoside, had very low experimental human oral bioavailability (3.2-14.9%), consistent with the expected absorption penalty of strongly ionized phosphate/phosphonate groups, although its multiple phosphates make this analog less directly transferable.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 2"],
      "record_ids": ["Record 2-1", "Record 2-2"]
    },
    {
      "claim": "Acyclovir and didanosine, adenine nucleoside analogs without the query's phosphonic acid, showed human oral bioavailability around 20-38% under fasting conditions, demonstrating that the adenine scaffold can be absorbed, but these records do not address the additional ionized-phosphonate barrier present in the query.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 1", "Molecule 3", "Molecule 5"],
      "record_ids": ["Record 1-1", "Record 3-1", "Record 3-2", "Record 5-1"]
    },
    {
      "claim": "Fludarabine monophosphate, a charged nucleotide phosphate, had 70% absolute oral bioavailability in humans and is the strongest counterexample; however, its ribose-phosphate structure and likely dephosphorylation before absorption differ from the metabolically stable acyclic phosphonate query, limiting transferability.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 6"],
      "record_ids": ["Record 6-1"]
    },
    {
      "claim": "Fed-state didanosine records (17-19%) are below the threshold but were obtained in the fed state, which is not the requested fasted condition; they therefore are not decisive for the fasted prediction.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 7"],
      "record_ids": ["Record 7-1", "Record 7-2"]
    },
    {
      "claim": "Records for SAMe, saquinavir, and pradefovir are structurally remote or refer to prodrug hepatic metabolism rather than free-phosphonate oral bioavailability; their low values are only weak, low-transfer support for the fail prediction. The P-gp substrate record for tenofovir is indirect and conflicting with Caco-2 permeability data, so it is not quantitative bioavailability evidence.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 4", "Molecule 8", "Molecule 14", "Molecule 15", "Molecule 16"],
      "record_ids": ["Record 4-1", "Record 8-1", "Record 8-2", "Record 8-3", "Record 8-4", "Record 8-5", "Record 8-6", "Record 8-7", "Record 8-8", "Record 8-9", "Record 8-10", "Record 14-1", "Record 15-1", "Record 16-1"]
    },
    {
      "claim": "Valomaciclovir stearate and theophylline show high human oral bioavailability, but they are not phosphonate-containing analogs and cannot override the phosphonate-specific absorption barrier; they are weak contradictory evidence.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 9", "Molecule 10"],
      "record_ids": ["Record 9-1", "Record 10-1"]
    }
  ],
  "final_prediction": "fail"
}
